#!/usr/bin/env python3
"""Configure the Android scaffold generated by Flutter for a consistent APK build."""
from __future__ import annotations

import re
from pathlib import Path

MIN_SDK = 24
COMPILE_SDK = 36
TARGET_SDK = 36
NDK_VERSION = "28.0.13004108"


def matching_brace(text: str, opening: int) -> int:
    """Return the closing brace matching text[opening] (best for generated Gradle files)."""
    depth = 0
    quote: str | None = None
    escaped = False
    line_comment = False
    block_comment = False
    i = opening
    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ""
        if line_comment:
            if ch == "\n":
                line_comment = False
        elif block_comment:
            if ch == "*" and nxt == "/":
                block_comment = False
                i += 1
        elif quote:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
        elif ch == "/" and nxt == "/":
            line_comment = True
            i += 1
        elif ch == "/" and nxt == "*":
            block_comment = True
            i += 1
        elif ch in ("'", '"'):
            quote = ch
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    raise RuntimeError("Unbalanced braces in generated Gradle file")


def set_kts_property(text: str, key: str, value: str) -> str:
    pattern = rf"(?m)^(\s*){re.escape(key)}\s*=\s*[^\n]+$"
    replacement = rf"\g<1>{key} = {value}"
    if re.search(pattern, text):
        return re.sub(pattern, replacement, text, count=1)
    android = re.search(r"(?m)^\s*android\s*\{", text)
    if not android:
        raise RuntimeError("Could not find android { } block")
    return text[:android.end()] + f"\n    {key} = {value}" + text[android.end():]


def configure_release_block(text: str, kotlin: bool) -> str:
    build_types = text.find("buildTypes")
    if build_types < 0:
        raise RuntimeError("Could not find buildTypes block in generated Gradle file")
    release = re.search(r"\brelease\s*\{", text[build_types:])
    if not release:
        raise RuntimeError("Could not find release build type")
    opening = build_types + release.end() - 1
    closing = matching_brace(text, opening)
    block = text[opening + 1:closing]

    minify_key = "isMinifyEnabled" if kotlin else "minifyEnabled"
    minify_value = "true"
    minify_pattern = rf"(?m)^(\s*){minify_key}\s*=\s*\w+\s*$" if kotlin else rf"(?m)^(\s*){minify_key}\s+\w+\s*$"
    if re.search(minify_pattern, block):
        block = re.sub(minify_pattern, rf"\g<1>{minify_key}{' = ' if kotlin else ' '}{minify_value}", block, count=1)
    else:
        block = "\n            " + (f"{minify_key} = true" if kotlin else f"{minify_key} true") + block

    proguard_line = (
        '            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")'
        if kotlin
        else "            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'"
    )
    if "proguard-rules.pro" not in block:
        block += "\n" + proguard_line + "\n        "

    return text[:opening + 1] + block + text[closing:]



def configure_jni_packaging(text: str) -> str:
    """Keep Android native libraries in modern APK packaging mode."""
    if "useLegacyPackaging" in text:
        return text
    android = re.search(r"(?m)^\s*android\s*\{", text)
    if not android:
        raise RuntimeError("Could not find android { } block")
    opening = android.end() - 1
    closing = matching_brace(text, opening)
    block = "\n    packaging { jniLibs { useLegacyPackaging = false } }\n"
    return text[:closing] + block + text[closing:]

def configure_kotlin_gradle(path: Path) -> None:
    text = path.read_text(encoding="utf-8")
    for key, value in (
        ("compileSdk", str(COMPILE_SDK)),
        ("ndkVersion", f'"{NDK_VERSION}"'),
    ):
        text = set_kts_property(text, key, value)

    text = set_kts_property(text, "minSdk", str(MIN_SDK))
    text = set_kts_property(text, "targetSdk", str(TARGET_SDK))
    text = configure_release_block(text, kotlin=True)
    text = configure_jni_packaging(text)
    path.write_text(text, encoding="utf-8")


def configure_groovy_gradle(path: Path) -> None:
    text = path.read_text(encoding="utf-8")

    def replace_line(pattern: str, replacement: str, label: str) -> None:
        nonlocal text
        if not re.search(pattern, text, flags=re.MULTILINE):
            raise RuntimeError(f"Could not find {label} in build.gradle")
        text = re.sub(pattern, replacement, text, count=1, flags=re.MULTILINE)

    replace_line(r"^(\s*)compileSdk(?:Version)?\s+.*$", rf"\g<1>compileSdkVersion {COMPILE_SDK}", "compile SDK")
    replace_line(r"^(\s*)ndkVersion\s+.*$", rf'\g<1>ndkVersion "{NDK_VERSION}"', "NDK version")
    replace_line(r"^(\s*)minSdk(?:Version)?\s+.*$", rf"\g<1>minSdkVersion {MIN_SDK}", "min SDK")
    replace_line(r"^(\s*)targetSdk(?:Version)?\s+.*$", rf"\g<1>targetSdkVersion {TARGET_SDK}", "target SDK")
    text = configure_release_block(text, kotlin=False)
    text = configure_jni_packaging(text)
    path.write_text(text, encoding="utf-8")



def android_identity(path: Path, kotlin: bool) -> tuple[str, str]:
    """Read the identity generated by Flutter without silently changing the app ID."""
    text = path.read_text(encoding="utf-8")
    if kotlin:
        namespace_match = re.search(r'(?m)^\s*namespace\s*=\s*"([^"]+)"\s*$', text)
        app_match = re.search(r'(?m)^\s*applicationId\s*=\s*"([^"]+)"\s*$', text)
    else:
        namespace_match = re.search(r"(?m)^\s*namespace\s+['\"]([^'\"]+)['\"]\s*$", text)
        app_match = re.search(r"(?m)^\s*applicationId\s+['\"]([^'\"]+)['\"]\s*$", text)
    if not namespace_match or not app_match:
        raise RuntimeError(f"Could not read namespace/applicationId from {path}")
    return namespace_match.group(1), app_match.group(1)


def configure_main_activity_package(package_id: str) -> None:
    """Keep MainActivity's package and path aligned with the generated namespace."""
    source_root = Path("android/app/src/main")
    candidates = list(source_root.rglob("MainActivity.kt")) + list(source_root.rglob("MainActivity.java"))
    if not candidates:
        raise FileNotFoundError("Flutter did not generate MainActivity.kt or MainActivity.java")

    for source in candidates:
        content = source.read_text(encoding="utf-8")
        kotlin = source.suffix == ".kt"
        pattern = r"(?m)^package[ \t]+[A-Za-z_][\w.]*[ \t]*;?[ \t]*$"
        if not re.search(pattern, content):
            raise RuntimeError(f"Could not locate package declaration in {source}")
        terminator = ";" if not kotlin else ""
        content = re.sub(pattern, f"package {package_id}{terminator}", content, count=1)

        language_dir = "kotlin" if kotlin else "java"
        destination_dir = source_root / language_dir / Path(*package_id.split("."))
        destination_dir.mkdir(parents=True, exist_ok=True)
        destination = destination_dir / source.name
        destination.write_text(content, encoding="utf-8")
        if destination.resolve() != source.resolve():
            source.unlink()


def main() -> None:
    kotlin = Path("android/app/build.gradle.kts")
    groovy = Path("android/app/build.gradle")
    if kotlin.exists():
        configure_kotlin_gradle(kotlin)
        namespace, application_id = android_identity(kotlin, kotlin=True)
    elif groovy.exists():
        configure_groovy_gradle(groovy)
        namespace, application_id = android_identity(groovy, kotlin=False)
    else:
        raise FileNotFoundError("Flutter did not generate android/app/build.gradle(.kts)")

    configure_main_activity_package(namespace)

    rules = Path("android/app/proguard-rules.pro")
    rules.parent.mkdir(parents=True, exist_ok=True)
    current = rules.read_text(encoding="utf-8") if rules.exists() else ""
    if "ai.onnxruntime" not in current:
        rules.write_text(current.rstrip() + "\n\n-keep class ai.onnxruntime.** { *; }\n", encoding="utf-8")

    print(
        f"Android project configured: namespace={namespace}, applicationId={application_id}, "
        f"minSdk={MIN_SDK}, compileSdk={COMPILE_SDK}, targetSdk={TARGET_SDK}, ndk={NDK_VERSION}"
    )


if __name__ == "__main__":
    main()
